sys_script.script:
(function executeRule(current, previous) {
    try {
        var allowedTransitions = {
            'requested': ['ordered'],
            'ordered': ['received'],
            'received': ['in_stock'],
            'in_stock': ['deployed', 'retired'],
            'deployed': ['in_repair', 'retired'],
            'in_repair': ['deployed'],
            'retired': ['disposed']
        };

        var oldState = previous.lifecycle_state.toString();
        var newState = current.lifecycle_state.toString();

        var allowed = allowedTransitions[oldState];
        if (!allowed || allowed.indexOf(newState) === -1) {
            current.setAbortAction(true);
            gs.addErrorMessage('Invalid lifecycle transition from ' + oldState + ' to ' + newState);
            gs.warn('TechDesk: Blocked invalid lifecycle transition from ' + oldState + ' to ' + newState + ' on asset ' + current.asset_tag);
        }
    } catch (e) {
        gs.error('TechDesk: Error in enforce-lifecycle - ' + e.message);
    }
})(current, previous);
